217: export function handleCrossReference(
218: 	target: ImmerState,
219: 	key: string | number | symbol,
220: 	value: any
221: ) {
222: 	const {scope_} = target
223: 	// Check if value is a draft from this scope
224: 	if (isDraft(value)) {
225: 		const state: ImmerState = value[DRAFT_STATE]
226: 		if (isSameScope(state, scope_)) {
227: 			// Register callback to update this location when the draft finalizes
228: 
229: 			state.callbacks_.push(function crossReferenceCleanup() {
230: 				// Update the target location with finalized value
231: 				prepareCopy(target)
232: 
233: 				const finalizedValue = getFinalValue(state)
234: 
235: 				updateDraftInParent(target, value, finalizedValue, key)
236: 			})
237: 		}
238: 	} else if (isDraftable(value)) {
239: 		// Handle non-draft objects that might contain drafts
240: 		target.callbacks_.push(function nestedDraftCleanup() {
241: 			const targetCopy = latest(target)
242: 
243: 			// For Sets, check if value is still in the set
244: 			if (target.type_ === ArchType.Set) {
245: 				if (targetCopy.has(value)) {
246: 					// Process the value to replace any nested drafts
247: 					handleValue(value, scope_.handledSet_, scope_)
248: 				}
249: 			} else {
250: 				// Maps/objects
251: 				if (get(targetCopy, key, target.type_) === value) {
252: 					if (
253: 						scope_.drafts_.length > 1 &&
254: 						((target as Exclude<ImmerState, SetState>).assigned_!.get(key) ??
255: 							false) === true &&
256: 						target.copy_
257: 					) {
258: 						// This might be a non-draft value that has drafts
259: 						// inside. We do need to recurse here to handle those.
260: 						handleValue(
261: 							get(target.copy_, key, target.type_),
262: 							scope_.handledSet_,
263: 							scope_
264: 						)
265: 					}
266: 				}
267: 			}
268: 		})
269: 	}
270: }
