272: export function handleValue(
273: 	target: any,
274: 	handledSet: Set<any>,
275: 	rootScope: ImmerScope
276: ) {
277: 	if (!rootScope.immer_.autoFreeze_ && rootScope.unfinalizedDrafts_ < 1) {
278: 		// optimization: if an object is not a draft, and we don't have to
279: 		// deepfreeze everything, and we are sure that no drafts are left in the remaining object
280: 		// cause we saw and finalized all drafts already; we can stop visiting the rest of the tree.
281: 		// This benefits especially adding large data tree's without further processing.
282: 		// See add-data.js perf test
283: 		return target
284: 	}
285: 
286: 	// Skip if already handled, frozen, or not draftable
287: 	if (
288: 		isDraft(target) ||
289: 		handledSet.has(target) ||
290: 		!isDraftable(target) ||
291: 		isFrozen(target)
292: 	) {
293: 		return target
294: 	}
295: 
296: 	handledSet.add(target)
297: 
298: 	// Process ALL properties/entries
299: 	each(target, (key, value) => {
300: 		if (isDraft(value)) {
301: 			const state: ImmerState = value[DRAFT_STATE]
302: 			if (isSameScope(state, rootScope)) {
303: 				// Replace draft with finalized value
304: 
305: 				const updatedValue = getFinalValue(state)
306: 
307: 				set(target, key, updatedValue, target.type_)
308: 
309: 				markStateFinalized(state)
310: 			}
311: 		} else if (isDraftable(value)) {
312: 			// Recursively handle nested values
313: 			handleValue(value, handledSet, rootScope)
314: 		}
315: 	})
316: 
317: 	return target
318: }
